C++ syntax examples demonstrating SIOF and solutions:

**Problem:**
```c++
class A {
public:
  static int x;
  A() { x = 10; }
};
int A::x = 0;

class B {
public:
  B() { std::cout << "A::x = " << A::x << "\n"; }
};

B b;
```
**Meyers Singleton (Solution):**
```c++
class Singleton {
private:
  static Singleton* instance;
  Singleton() {}
public:
  static Singleton& getInstance() {
    static Singleton theInstance; // Initialized only once
    return theInstance;
  }
};
Singleton* Singleton::instance = nullptr;
```
**Static Function Initialization (Solution):**
```c++
class A {
public:
  static int x; 
  static int getX() { static int x = 10; return x; }
};
int A::x = 0;
int main() { std::cout << A::getX() << std::endl; }
```
